use crate::aap::caps::kb_read;

/// Bound from the node contract: `ensures len(question) <= 512`.
const MAX_QUESTION_CHARS: usize = 512;

/// Returned when the knowledge base has nothing for the question, so that
/// `ensures present(knowledge)` holds on every path.
const NO_MATCH: &str = "no knowledge-base entries matched this question";

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        // Enforce the output bound on every path, not only when the input
        // `requires` clause holds. Length is counted in characters, matching
        // Python's `len` on `str`.
        let question: String = query
            .query
            .question
            .chars()
            .take(MAX_QUESTION_CHARS)
            .collect();

        let mut knowledge: Vec<String> = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(String::from(NO_MATCH));
        }

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
